CREATE TABLE IF NOT EXISTS vl_users (id INT PRIMARY KEY, username VARCHAR(80) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, totp TEXT NOT NULL, last_step BIGINT NOT NULL DEFAULT -1, session_version INT NOT NULL DEFAULT 1) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS vl_recovery (id INT AUTO_INCREMENT PRIMARY KEY, hash VARCHAR(255) NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS vl_pages (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(200) NOT NULL, route VARCHAR(240) NOT NULL UNIQUE, draft MEDIUMTEXT NOT NULL, published MEDIUMTEXT NULL, revision INT NOT NULL DEFAULT 1, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS vl_history (id INT AUTO_INCREMENT PRIMARY KEY, page_id INT NOT NULL, data MEDIUMTEXT NOT NULL, action VARCHAR(40) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(page_id) REFERENCES vl_pages(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS vl_menu (id INT AUTO_INCREMENT PRIMARY KEY, parent_id INT NULL, page_id INT NULL, label VARCHAR(200) NOT NULL, url VARCHAR(2048) NOT NULL DEFAULT '', position INT NOT NULL DEFAULT 0, placement VARCHAR(20) NOT NULL DEFAULT 'header', visible TINYINT NOT NULL DEFAULT 1, FOREIGN KEY(page_id) REFERENCES vl_pages(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS vl_files (id INT AUTO_INCREMENT PRIMARY KEY, page_id INT NULL, path VARCHAR(600) NOT NULL UNIQUE, name VARCHAR(240) NOT NULL, size BIGINT NOT NULL, sha256 CHAR(64) NOT NULL, comment TEXT NOT NULL, trash VARCHAR(80) NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(page_id) REFERENCES vl_pages(id) ON DELETE SET NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS vl_attempts (id CHAR(64) PRIMARY KEY, count INT NOT NULL DEFAULT 0, until_at BIGINT NOT NULL DEFAULT 0, window_at BIGINT NOT NULL DEFAULT 0) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS vl_audit (id BIGINT AUTO_INCREMENT PRIMARY KEY, action VARCHAR(80) NOT NULL, detail TEXT NOT NULL, ip_hash CHAR(64) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS vl_previews (token CHAR(64) PRIMARY KEY, data MEDIUMTEXT NOT NULL, expires BIGINT NOT NULL) ENGINE=InnoDB;
